import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"매개변수 다운로드 실패","description":"","frontmatter":{},"headers":[],"relativePath":"ko/qgc-user-guide/troubleshooting/parameter_download.md","filePath":"ko/qgc-user-guide/troubleshooting/parameter_download.md"}`),a={name:`ko/qgc-user-guide/troubleshooting/parameter_download.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="매개변수-다운로드-실패" tabindex="-1">매개변수 다운로드 실패 <a class="header-anchor" href="#매개변수-다운로드-실패" aria-label="Permalink to “매개변수 다운로드 실패”">​</a></h1><p>대부분의 매개변수 다운로드 실패 현상은 노이즈가 많고 손실률이 높은 통신 네트워크에서 발생합니다. 매개변수 프로토콜에는 이러한 경우에 대한 재시도 기능이 있으나, 결국 실패합니다. 이 시점에서 QGroundControl에서 전체 세트 또는 매개변수를 검색할 수 없다는 오류가 표시됩니다.</p><p>이 상태에서도 기체의 비행은 가능하지만, 권장되는 방식은 아닙니다. 그리고, 기체 설정 페이지를 사용할 수 없습니다.</p><p>You can see the loss rate for your link from the <a href="./../settings_view/telemetry.html">App Settings &gt; Telemetry</a> page. 높은 한 자릿수 손실률조차도 계획 프로토콜의 간헐적 실패로 이어질 수 있습니다. Higher loss rates could lead to 100% failure.</p><p>더 많은 펌웨어나 QGroundControl 버그가 존재할 수 있습니다. To see the details of the back and forth message traffic of the protocol you can turn on the <code>FactSystem.ParameterManager</code> <a href="./../troubleshooting/console_logging.html">console logging</a> category.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};